/**
 * Kind names an operation.
 *
 * The operations a change set may carry, in the order the schema lists them;
 * ChangeOp["op"] is the same union.
 *
 * - `set_content`: Replace an edition's content with text (placeholder form) or
 *   runs. With if_match "absent" it creates the edition.
 * - `replace_text`: Change text inside an edition by find, by code-point
 *   offsets or by run positions, keeping inline codes and structure.
 * - `set_attribute`: Change a writable attribute of an inline code, such as a
 *   link's href.
 * - `mark`: Wrap text in a new paired code of a vocabulary type, such as
 *   fmt:bold.
 * - `remove_edition`: Remove one edition of a block.
 * - `annotate`: Add a stand-off annotation to an edition, or replace the one
 *   with the same type and id.
 * - `unannotate`: Remove an annotation by type and id.
 * - `insert_block`: Add a block to a document, after or before a block key.
 * - `delete_block`: Remove a block from a document.
 * - `native`: A format-specific operation, guarded by the document digest.
 * - `decide`: Record a review decision on the edition revision read. An agent
 *   sends only advise.
 * - `term`: Write or delete a term in the terms store.
 * - `memory`: Add or delete a content-memory pair.
 * - `recipe`: Set one recipe field through its allowlist.
 */
export type ChangeOpKind =
  | "set_content"
  | "replace_text"
  | "set_attribute"
  | "mark"
  | "remove_edition"
  | "annotate"
  | "unannotate"
  | "insert_block"
  | "delete_block"
  | "native"
  | "decide"
  | "term"
  | "memory"
  | "recipe";
export const CHANGE_OP_KINDS: readonly ChangeOpKind[] = ["set_content", "replace_text", "set_attribute", "mark", "remove_edition", "annotate", "unannotate", "insert_block", "delete_block", "native", "decide", "term", "memory", "recipe"];

/**
 * The operation an OpResult names: one a change set may carry, or one a tool in
 * a flow applies in process, which no change set carries.
 *
 * - `provenance`: records how a tool produced an edition: its status and
 *   origin. Only a tool in a flow sends it, in process; no change set carries
 *   it, and the schema does not list it.
 */
export type ResultOpKind = ChangeOpKind | "provenance";

/**
 * SetStatus is the outcome of a whole change set.
 *
 * Mirrors core/change.SetStatus.
 *
 * - `applied`: every operation landed.
 * - `refused`: an operation was refused and nothing was written.
 * - `previewed`: the change set was computed and checked, and nothing was
 *   written because the mode was preview.
 * - `partial`: an I/O error interrupted the final writes. The documents that
 *   landed say written.
 */
export type ChangeSetStatus = "applied" | "refused" | "previewed" | "partial";
export const CHANGE_SET_STATUSES: readonly ChangeSetStatus[] = ["applied", "refused", "previewed", "partial"];

/**
 * OpStatus is the outcome of one operation.
 *
 * Mirrors core/change.OpStatus.
 *
 * - `applied`: the operation changed what it addresses.
 * - `unchanged`: what it addresses already says that.
 * - `refused`: the operation was refused; Error says why.
 * - `not_applied`: another operation of the change set was refused, so this one
 *   was not written; BlockedBy names it.
 * - `previewed`: the operation would apply; the mode was preview.
 */
export type ChangeOpStatus = "applied" | "unchanged" | "refused" | "not_applied" | "previewed";
export const CHANGE_OP_STATUSES: readonly ChangeOpStatus[] = ["applied", "unchanged", "refused", "not_applied", "previewed"];

/**
 * Code is why an operation or a change set was refused. The set is closed:
 * every transport maps each code once (ExitCode, HTTPStatus), and each code
 * tells the sender which of a few things to do next.
 *
 * Mirrors core/change.Code.
 *
 * - `invalid`: the change set does not decode, fails its schema, or contradicts
 *   itself. The error carries the JSON pointer. Fix the change set.
 * - `not_found`: a reference resolves to no document, block or edition, or a
 *   find matches nothing. Retarget or re-read.
 * - `ambiguous`: a key or a find matches more than one thing. The error carries
 *   the candidates. Narrow it.
 * - `stale`: if_match no longer holds, or require_basis is set and the basis
 *   moved; Field says which. The result carries the current revision and
 *   content. Re-read, rebase and resend.
 * - `doc_changed`: the document changed under the commit and one retry could
 *   not settle it. Resend.
 * - `guard`: the result would drop, add or unbalance inline codes, or flatten
 *   structure (Subcode says which). Fix the content.
 * - `gate_failed`: a failing rule finds a violation the edit introduces. Fix
 *   the wording, or a person overrides.
 * - `unsupported`: the format, edition or home lacks the capability the
 *   operation needs. The error names it.
 * - `not_permitted`: the sender's policy refuses the operation. Ask a person.
 * - `budget_exceeded`: a resource bound was hit. Split the change.
 * - `unreachable`: the server or backend holding the content did not answer.
 *   Retry later.
 */
export type ChangeErrorCode =
  | "invalid"
  | "not_found"
  | "ambiguous"
  | "stale"
  | "doc_changed"
  | "guard"
  | "gate_failed"
  | "unsupported"
  | "not_permitted"
  | "budget_exceeded"
  | "unreachable";
export const CHANGE_ERROR_CODES: readonly ChangeErrorCode[] = ["invalid", "not_found", "ambiguous", "stale", "doc_changed", "guard", "gate_failed", "unsupported", "not_permitted", "budget_exceeded", "unreachable"];

/**
 * Subcode narrows a guard refusal.
 *
 * Mirrors core/change.Subcode.
 *
 * - `codes_changed`: the result drops, repeats, reorders or unbalances an
 *   inline code its constraints protect, or names a code the reference does not
 *   hold.
 * - `structure_lost`: the result would flatten a plural or select, or an edit
 *   reaches into one without naming its branch with a path.
 * - `bad_position`: a position is outside the sequence it addresses.
 * - `overlap`: two edits of one operation overlap, or a position names text an
 *   earlier operation of the change set changed in the same edition.
 */
export type ChangeGuardSubcode = "codes_changed" | "structure_lost" | "bad_position" | "overlap";
export const CHANGE_GUARD_SUBCODES: readonly ChangeGuardSubcode[] = ["codes_changed", "structure_lost", "bad_position", "overlap"];

/**
 * Editions says how a format holds a document's editions.
 *
 * Mirrors core/change.Editions.
 *
 * - `one-per-file`: a file holds one edition, and each other edition of the
 *   document lives in a file of its own, as a project's target files do: the
 *   monolingual formats.
 * - `in-file`: one file holds every edition, as a bilingual interchange file
 *   (PO, XLIFF, TMX, xcstrings) does.
 */
export type FormatEditions = "one-per-file" | "in-file";
export const FORMAT_EDITIONS: readonly FormatEditions[] = ["one-per-file", "in-file"];

/**
 * ActorKind says what kind of sender a change has.
 *
 * Mirrors core/change.ActorKind.
 *
 * - `person`: is someone using kapi, Kapi Desktop or a Bowrain editor.
 * - `agent`: is an AI working through kapi's agent surfaces.
 * - `tool`: is a tool running in a flow.
 */
export type ChangeActorKind = "person" | "agent" | "tool";
export const CHANGE_ACTOR_KINDS: readonly ChangeActorKind[] = ["person", "agent", "tool"];

/** The HTTP status a transport answers each refusal with. Mirrors core/change.Code.HTTPStatus. */
export const CHANGE_ERROR_HTTP_STATUS: Readonly<Record<ChangeErrorCode, number>> = {
  invalid: 400,
  not_found: 404,
  ambiguous: 409,
  stale: 409,
  doc_changed: 409,
  guard: 422,
  gate_failed: 422,
  unsupported: 422,
  not_permitted: 403,
  budget_exceeded: 413,
  unreachable: 503,
};

/** The exit code a command line returns for each refusal. Mirrors core/change.Code.ExitCode. */
export const CHANGE_ERROR_EXIT_CODE: Readonly<Record<ChangeErrorCode, number>> = {
  invalid: 2,
  not_found: 3,
  ambiguous: 3,
  stale: 3,
  doc_changed: 3,
  guard: 3,
  gate_failed: 3,
  unsupported: 3,
  not_permitted: 3,
  budget_exceeded: 3,
  unreachable: 5,
};

// ── The result (kapi.change-result/v1) ──────────────────────────────────────

/**
 * Ref addresses one edition of one block in one document.
 *
 * Doc is a project-relative path, an archive member (container!entry), an item
 * path inside a server stream, or a workspace document key. Block is the block
 * key: the durable key reconciliation assigned (Block.Unit) where there is one,
 * else the structural name the format reports. Edition is the edition key,
 * canonical; the zero key is the document's own edition.
 *
 * The JSON core/change.Ref writes, as a result and a finding name what they are
 * about: a key it leaves out when empty is optional here. A read's reference
 * always names its block, and is a ChangeRef.
 */
export interface ResultRef {
  doc: string;
  block?: string;
  edition?: string;
}

/**
 * Result is the outcome of a change set.
 *
 * Mirrors core/change.Result.
 */
export interface ChangeResult {
  /** Schema is ResultSchemaID. */
  schema: typeof CHANGE_RESULT_SCHEMA_ID;
  status: ChangeSetStatus;
  /**
   * Record is the id of the recorded edit, when something was written and
   * recorded.
   */
  record: string | null;
  docs: DocResult[];
  ops: OpResult[];
  /**
   * Error is why the change set was refused as a whole, before any operation
   * was considered: it did not decode, or the request carrying it was refused.
   * Status is then refused, and Docs and Ops are empty.
   */
  error?: ChangeError;
}

/**
 * DocResult is the outcome for one document.
 *
 * Mirrors core/change.DocResult.
 */
export interface DocResult {
  doc: string;
  /**
   * Home is where the document's text lives: file, workspace or stream:<id>.
   */
  home?: string;
  /**
   * File is the file the entry is about when it is not the document itself: the
   * file of one edition of the document, which Edition names.
   */
  file?: string;
  edition?: string;
  written: boolean;
  /**
   * Before and After are the file digests around the change. Before is empty
   * for a file the change creates; After is null when nothing was written.
   */
  before?: string;
  after: string | null;
  findings?: ChangeFinding[];
  /** Diff, in a preview, is what the change would write, as a unified diff. */
  diff?: string;
}

/**
 * OpResult is the outcome of one operation.
 *
 * Mirrors core/change.OpResult.
 */
export interface OpResult {
  /** I is the operation's index in the change set. */
  i: number;
  op: ResultOpKind;
  status: ChangeOpStatus;
  at?: ResultRef;
  /** Before and After are the edition's revisions around the operation. */
  before?: string;
  after?: string;
  /**
   * Basis is the authoritative edition's revision a derived edition was made
   * from, as recorded.
   */
  basis?: string;
  /** ID is the id of the annotation an annotate wrote. */
  id?: string;
  /**
   * Resolved echoes every position the operation resolved, in the order of its
   * edits, so the sender learns the canonical form.
   */
  resolved?: ResolvedSpan[];
  /**
   * Invalidates lists the derived editions whose basis this operation moved.
   */
  invalidates?: Invalidation[];
  /**
   * Findings are guard findings the operation landed with, under a report
   * disposition.
   */
  findings?: ChangeFinding[];
  error?: ChangeError;
  /** Current is the edition as it stands, on a stale refusal. */
  current?: CurrentEdition;
  /**
   * BlockedBy is the index of the refused operation that kept this one from
   * being written.
   */
  blocked_by?: number;
}

/**
 * Finding is one thing a check of the changed content found.
 *
 * Mirrors core/change.Finding.
 */
export interface ChangeFinding {
  /** Rule names the rule, such as terms.vocabulary or guard.codes_changed. */
  rule: string;
  message: string;
  /**
   * Fails says whether the finding fails a gate; an advisory or suggested rule
   * reports without failing.
   */
  fails: boolean;
  suggested?: boolean;
  at?: ResultRef;
}

/**
 * Resolved is a span the service resolved, with the path of the run sequence it
 * lies in.
 *
 * Mirrors core/change.Resolved.
 */
export interface ResolvedSpan {
  path?: RunPath;
  start: RunPos;
  end: RunPos;
}

/**
 * Invalidation names a derived edition an edit made stale.
 *
 * Mirrors core/change.Invalidation.
 */
export interface Invalidation {
  edition: string;
  /**
   * Reason is basis_moved: the authoritative edition it was made from changed.
   */
  reason: string;
}

/**
 * Current is an edition as it stands, sent with a stale refusal so the sender
 * can rebase without another read.
 *
 * Mirrors core/change.Current.
 */
export interface CurrentEdition {
  rev: string;
  /** Text is the edition in the placeholder form a read shows. */
  text?: string;
}

/**
 * Error is a refusal. Code is always set; the other fields carry what the code
 * says it carries.
 *
 * Mirrors core/change.Error.
 */
export interface ChangeError {
  code: ChangeErrorCode;
  subcode?: ChangeGuardSubcode;
  /**
   * Field names the operation field at fault, as a path inside the operation:
   * "if_match", "basis", "edits/1/find".
   */
  field?: string;
  /**
   * Pointer is the JSON pointer of what failed to decode, into the change set
   * as sent ("/ops/2/edits/0/find").
   */
  pointer?: string;
  message: string;
  /**
   * Candidates are what an ambiguous reference or find matched, or what a
   * reference that resolved to nothing might have meant.
   */
  candidates?: ErrorCandidate[];
  /**
   * Searched is, for a find that matches nothing, the run sequence it searched:
   * the path that reaches it and its text in placeholder form.
   */
  searched?: FindSearched;
  /** Expected and Found describe a guard refusal. */
  expected?: string;
  found?: string;
  /** Capability names what an unsupported operation needs. */
  capability?: string;
}

/**
 * Candidate is one thing a reference or a find could mean.
 *
 * Mirrors core/change.Candidate.
 */
export interface ErrorCandidate {
  /** Key is a block key or an edition key. */
  key?: string;
  /** Rev is the candidate's revision. */
  rev?: string;
  /**
   * Text is the first 80 characters of the candidate's content, or the text
   * around a match.
   */
  text?: string;
  /**
   * Occurrence is the 1-based number of a find match, the value to send as
   * occurrence to choose it.
   */
  occurrence?: number;
  /** At is where a find match lies. */
  at?: ResolvedSpan;
}

/**
 * Searched is the run sequence a find searched: the path that reaches it, empty
 * for the edition's own text, and that text in placeholder form.
 *
 * Mirrors core/change.Searched.
 */
export interface FindSearched {
  path?: RunPath;
  text: string;
}

// ── A read page (Service.Read) ──────────────────────────────────────────────

/**
 * ReadRequest names what to read: a document, optionally only some of its
 * blocks and the editions that live in files of their own, a page at a time.
 *
 * Mirrors core/change.ReadRequest.
 */
export interface ReadRequest {
  doc: string;
  /** Blocks names blocks by key; empty reads every block. */
  blocks?: string[];
  /**
   * Editions names the editions to show that live in files of their own. The
   * editions a document holds itself are always shown.
   */
  editions?: string[];
  /** Cursor continues a read where the page that returned it ended. */
  cursor?: string;
  /** Limit is the most blocks a page holds; zero is DefaultReadLimit. */
  limit?: number;
}

/**
 * Page is one page of a document's blocks.
 *
 * Mirrors core/change.Page.
 */
export interface ReadPage {
  doc: string;
  home: string;
  format: string;
  /** Head is the digest of the document the page was read from. */
  head: string;
  blocks: BlockRead[];
  /** Next continues the read; empty on the last page. */
  next?: string;
}

/**
 * BlockRead is a block as a read shows it: the reference to copy into an
 * operation, the revision to send as if_match, the content in placeholder text,
 * the inline codes and structures it holds, its other editions, and the
 * operations it accepts.
 *
 * Mirrors core/change.BlockRead.
 */
export interface BlockRead {
  ref: ChangeRef;
  rev: string;
  text: string;
  /**
   * Codes maps the id a code shows in placeholder text (1, /1 is its closing
   * half, 1/ a placeholder, sub:1 a subblock) to what it is.
   */
  codes?: Record<string, CodeRead>;
  /**
   * Structures lists the plurals and selects, each with the path an operation
   * names to reach one of its branches.
   */
  structures?: StructureRead[];
  editions?: Record<string, EditionRead>;
  ops: ChangeOpKind[];
}

/**
 * CodeRead is an inline code as a read shows it.
 *
 * Mirrors core/change.CodeRead.
 */
export interface CodeRead {
  kind: string;
  type?: string;
  attrs?: Record<string, string>;
  /**
   * Equiv is the code's equivalent text, such as the name of the variable a
   * placeholder stands for, and Disp the short label an editor shows on it.
   * Both are labels: a read leaves out either one that repeats the code's
   * native form (an ICU argument, a printf specifier, a tag), which no read
   * shows.
   */
  equiv?: string;
  disp?: string;
  /** Writable are the attributes set_attribute can change on the code. */
  writable?: string[];
}

/**
 * StructureRead is a plural or a select.
 *
 * Mirrors core/change.StructureRead.
 */
export interface StructureRead {
  path: RunPath;
  kind: string;
  pivot?: string;
  /** Branches maps each plural form or select case to its text. */
  branches: Record<string, string>;
}

/**
 * EditionRead is an edition other than the document's own.
 *
 * Mirrors core/change.EditionRead.
 */
export interface EditionRead {
  rev: string;
  text: string;
  /**
   * Codes lists the edition's inline codes where they differ from the block's;
   * absent, the block's codes are the edition's.
   */
  codes?: Record<string, CodeRead>;
  /**
   * Structures lists the edition's own plurals and selects, each with the path
   * an operation on the edition names to reach one of its branches.
   */
  structures?: StructureRead[];
  status?: string;
  /**
   * Basis is the authoritative edition's revision the edition was made from,
   * where the host keeps it.
   */
  basis?: string;
  /** Stale says the authoritative edition has moved since the basis. */
  stale: boolean;
}

// ── What a format supports (Service.Describe) ───────────────────────────────

/**
 * DescribeRequest names what to describe: a format by name, or the format of a
 * document.
 *
 * Mirrors core/change.DescribeRequest.
 */
export interface DescribeRequest {
  format?: string;
  doc?: string;
}

/**
 * Description is what one format supports of the contract: the table
 * describe_format and `kapi formats --ops` publish. An operation the format
 * refuses as unsupported is null.
 *
 * Mirrors core/change.Description.
 */
export interface FormatDescription {
  format: string;
  editions: FormatEditions;
  ops: FormatOpTable;
  native: FormatNativeOp[];
}

/**
 * OpTable lists, per content operation, what a format supports; nil is
 * unsupported.
 *
 * Mirrors core/change.OpTable.
 */
export interface FormatOpTable {
  set_content: SetContentSupport | null;
  replace_text: OpSupported | null;
  set_attribute: Record<string, string[]> | null;
  mark: MarkSupport | null;
  remove_edition: OpSupported | null;
  annotate: AnnotateSupport | null;
  unannotate: OpSupported | null;
  insert_block: OpSupported | null;
  delete_block: OpSupported | null;
}

/**
 * SetContentSupport qualifies set_content: the content forms accepted, and the
 * vocabulary types a runs payload may introduce as new codes.
 *
 * Mirrors core/change.SetContentSupport.
 */
export interface SetContentSupport {
  forms: string[];
  new_codes: string[];
}

/**
 * MarkSupport lists the vocabulary types mark may create.
 *
 * Mirrors core/change.MarkSupport.
 */
export interface MarkSupport {
  types: string[];
}

/**
 * AnnotateSupport lists the annotation types the format writes inline; every
 * other annotation stays stand-off.
 *
 * Mirrors core/change.AnnotateSupport.
 */
export interface AnnotateSupport {
  inline: string[];
}

/**
 * Supported marks an operation a format supports with nothing to qualify it.
 *
 * Mirrors core/change.Supported.
 */
export type OpSupported = Record<string, never>;

/**
 * NativeOp is a format-specific operation: its name and the JSON Schema of its
 * arguments.
 *
 * Mirrors core/format.NativeOp.
 */
export interface FormatNativeOp {
  name: string;
  schema?: unknown;
}

// ── An edition's recorded changes (Service.History) ─────────────────────────

/**
 * HistoryRequest names the edition whose recorded changes to list.
 *
 * Mirrors core/change.HistoryRequest.
 */
export interface HistoryRequest {
  /**
   * Ref is the edition as a read reports it. A reference to the file one
   * edition lives in, with no edition, names that edition, as a read of that
   * file does.
   */
  ref: ChangeRef;
  /**
   * Limit is the most entries the history holds; zero is DefaultHistoryLimit.
   */
  limit?: number;
}

/**
 * History is the recorded changes to one edition, most recent first.
 *
 * Mirrors core/change.History.
 */
export interface EditionHistory {
  /** Ref is the edition, canonical. */
  ref: ChangeRef;
  /**
   * Rev is the edition's revision now, "absent" for an edition the block does
   * not hold.
   */
  rev: string;
  entries: HistoryEntry[];
}

/**
 * HistoryEntry is one recorded change to an edition.
 *
 * Mirrors core/change.HistoryEntry.
 */
export interface HistoryEntry {
  /**
   * Record is the id of the recorded edit (content.edit) that made the change.
   */
  record: string;
  /**
   * Before and After are the edition's revisions around the change: Before is
   * "absent" for an edition the change created, and After for one it removed.
   */
  before: string;
  after: string;
  /**
   * Basis is the authoritative edition's revision a derived edition was made
   * from, when the change recorded one.
   */
  basis?: string;
  /**
   * Actor is who made the change, null when nobody knows who, as for an edit
   * made outside kapi.
   */
  actor: ChangeActor | null;
  /**
   * Origin is the surface that applied the change: apply, desktop, mcp,
   * flow:<name>, merge, pull or observed.
   */
  origin?: string;
  /** At is when the change was recorded. */
  at: string;
}

/**
 * Actor is who sends a change. The transport sets it; a change set never names
 * its own sender.
 *
 * Mirrors core/change.Actor.
 */
export interface ChangeActor {
  kind: ChangeActorKind;
  name?: string;
  session?: string;
}
